      },
      {
        "group": "건강",
        "class_code": "HH_EYE_DMG",
        "category": "1",
        "raw": "심한 눈 손상성/눈 자극성 | 구분 1",
        "line": "p1:L29"
      },
      {
        "group": "환경",
        "class_code": "ENV_AQ_CHRONIC",
        "category": "2",
        "raw": "수생 환경 유해성 - 만성 | 구분 2",
        "line": "p1:L30"
      }
    ],
    "signal_word": "위험",
    "pictograms": [
      {
        "code": "GHS05"
      },
      {
        "code": "GHS09"
      }
    ],
    "h_statements": [
      {
        "code": "H290",
        "text": "금속을 부식시킬 수 있음",
        "line": "p2:L8"
      },
      {
        "code": "H315",
        "text": "피부에 자극을 일으킴",
        "line": "p2:L9"
      },
      {
        "code": "H318",
        "text": "눈에 심한 손상을 일으킴",
        "line": "p2:L10"
      },
      {
        "code": "H411",
        "text": "장기적인 영향에 의해 수생생물에게 유독함",
        "line": "p2:L11"
      }
    ],
    "p_statements": [
      {
        "code": "P264",
        "type": "예방",
        "text": "취급 후에는 얼굴과 손, 노출된 피부 부위를 철저히 씻으시오",
        "line": "p2:L13"
      },
      {
        "code": "P273",
        "type": "예방",
        "text": "환경으로 배출하지 마시오",
        "line": "p2:L14"
      },
      {
        "code": "P234",
        "type": "예방",
        "text": "원래의 용기에만 보관하시오",
        "line": "p2:L15"
      },
      {
        "code": "P280",
        "type": "예방",
        "text": "보호장갑, 보호의, 보안경, 안면보호구를 착용하시오",
        "line": "p2:L16"
      },
      {
        "code": "P321",
        "type": "대응",
        "text": "이 경고표지의 보충 응급조치 지침을 참조하여 처치를 하시오",
        "line": "p2:L18"
      },
      {
        "code": "P305 + P351 + P338",
        "type": "대응",
        "text": "눈에 묻으면: 몇 분간 물로 조심해서 씻으시오. 가능하면 콘택트렌즈를 제거하시오. 계속 씻으시오",
        "line": "p2:L19"
      },
      {
        "code": "P310",
        "type": "대응",
        "text": "즉시 의료기관(의사)의 진찰을 받으시오",
        "line": "p2:L20"
      },
      {
        "code": "P302 + P352",
        "type": "대응",
        "text": "피부에 묻으면:다량의 물과 비누로 씻으시오",
        "line": "p2:L21"
      },
      {
        "code": "P332 + P313",
        "type": "대응",
        "text": "피부 자극이 나타나면: 의학적인 조치/조언을 받으시오",
        "line": "p2:L22"
      },
      {
        "code": "P362 + P364",
        "type": "대응",
        "text": "오염된 의류를 벗고 다시 사용 전 세척하시오",
        "line": "p2:L23"
      },
      {
        "code": "P391",
        "type": "대응",
        "text": "누출물을 모으시오",
        "line": "p2:L24"
      },
      {
        "code": "P390",
        "type": "대응",
        "text": "물질손상을 방지하기 위해 누출물을 흡수시키시오",
        "line": "p2:L25"
      },
      {
        "code": "P406",
        "type": "저장",
        "text": "금속부식성 물질이므로 제조자 또는 행정관청에서 정한 내부식성 용기 등에 보관하시오",
        "line": "p2:L27"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "해당되는 경우 현지, 지역, 국가 및 국제 법규에 명시된 내용에 따라 내용물과 용기를 폐기하시오",
        "line": "p2:L29"
      }
    ],
    "other_hazards": [
      {
        "value": "자료 없음.",
        "line": "p2:L30"
      }
    ]
  ,
    "nfpa": {
      "health": 3,
      "fire": 0,
      "reactivity": 2
    }
  ,
    "lines": {
      "pictograms": "p2:L4",
      "nfpa": "p2:L31"
    }
  }
,
  "narratives": [
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "가. 유해성·위험성 분류",
      "start": "p1:L25",
      "end": "p1:L30"
    },
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "나. 예방조치 문구를 포함한 경고 표지 항목",
      "start": "p1:L31",
      "end": "p2:L29"
    },
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "다. 유해성․위험성 분류기준에 포함되지 않는 기타 유해성․위험성",
      "start": "p2:L30",
